/**
 * social-conversation — chatMessenger + chatWhatsapp registry entries.
 *
 * The whatsapp branch is a 1:1 port of the reference chat-scene.jsx the
 * user shipped: warm-sand background with the line-art SVG pattern,
 * compose bar at the bottom, phased read receipts (clock → grey single
 * → grey double → blue), and date chips between message groups. The
 * scene closes on the last message's read-receipt phase landing on
 * blue — no trailing typing bubble (that left the scene hanging on a
 * "still typing" beat with no payoff). Reply quotes intentionally not
 * implemented per user direction.
 *
 * Timing keys off `progress` mapped onto the reference's 16s timeline
 * so the same beat structure plays at any scene duration. Real-time
 * seconds (`progress * sceneDuration`) drive only the typing-dot ripple
 * so its 1.5 Hz cadence is stable regardless of scene length.
 *
 * Schema: msg1..msg5 + dateChip1 + dateChip2. msg5 and chips are
 * optional — leaving them empty falls back to a 4-message ping-pong
 * which is what existing saved scenes use.
 *
 * Theme is set by the registry entry (chatMessenger vs chatWhatsapp).
 * iMessage uses a simpler clean-bubble layout sharing the same
 * timing/sequencing logic.
 */

import * as React from "react";
import type { VariableField } from "../video-config";
import type { SceneTemplateProps } from "./types";
import { interpolate } from "../react-animations/animation-utils";
import { normalizeTextVar } from "./normalize-var";

const CLAMP = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

/* Reference timeline length — every reveal time below is a fraction of
 * this. Scaling progress by this constant lets us key off the original
 * seconds in the reference comments without re-computing fractions. */
const REF_DURATION = 16;

/* easeOutBack — same overshoot curve the reference uses for pop-ins. */
function easeOutBack(t: number): number {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
}

/* ── WhatsApp palette (1:1 from reference) ─────────────────────────── */
const WA = {
  bg: "#EFE7DC",
  incomingBubble: "#FFFFFF",
  outgoingBubble: "#D9F4C7",
  text: "#0E0E0E",
  textMuted: "#6E6E73",
  accent: "#0A8F76",
  chipBg: "#F1E9D8",
  chipText: "#3C342A",
  navBg: "#F1E9DA",
  inputBg: "#FFFFFF",
  inputBorder: "rgba(0,0,0,0.06)",
  outgoingTime: "#5C6B4E",
};

/* ── iMessage palette ───────────────────────────────────────────────── */
const IM = {
  bg: "#ffffff",
  bubbleOut: "#007AFF",
  bubbleIn: "#E9E9EB",
  textOut: "#ffffff",
  textIn: "#000000",
  dotsColor: "#8E8E93",
};

interface ChatMessage {
  side: "left" | "right";
  text: string;
  /* Reference timing for whatsapp 5-message structure. These are the
   * exact seconds from chat-scene.jsx so the cadence ports cleanly. */
  typingStart: number;
  bubbleStart: number;
  time: string;
}

/* WhatsApp reference timing (matches chat-scene.jsx exactly):
 *   msg1 in1: typing 0.6→1.4, bubble at 1.4
 *   msg2 in2: typing 2.2→3.0, bubble at 3.0
 *   msg3 in3: typing 3.8→4.8, bubble at 4.8
 *   chip1 (Monday): 5.8→6.2
 *   msg4 ob1: typing 6.2→7.2, bubble at 7.2
 *   chip2 (Yesterday): 9.6→10.0
 *   msg5 ob2: typing 10.0→11.0, bubble at 11.0
 *   trailing typing left: 13.6→15.0 */
const WA_TIMING_5: Array<{ typingStart: number; bubbleStart: number; time: string }> = [
  { typingStart: 0.6,  bubbleStart: 1.4, time: "21:54" },
  { typingStart: 2.2,  bubbleStart: 3.0, time: "21:55" },
  { typingStart: 3.8,  bubbleStart: 4.8, time: "21:56" },
  { typingStart: 6.2,  bubbleStart: 7.2, time: "12:35" },
  { typingStart: 10.0, bubbleStart: 11.0, time: "11:17" },
];

/* When fewer than 5 messages are filled, redistribute timing across
 * the available message window so the beats stay evenly paced. */
function timingForCount(count: number): Array<{ typingStart: number; bubbleStart: number; time: string }> {
  if (count >= 5) return WA_TIMING_5.slice(0, count);
  // Evenly space N messages across the 12s message window with the same
  // ~1s typing+bubble cadence per slot.
  const slot = 12 / count;
  const out: Array<{ typingStart: number; bubbleStart: number; time: string }> = [];
  for (let i = 0; i < count; i++) {
    const start = 0.6 + i * slot;
    out.push({
      typingStart: start,
      bubbleStart: start + slot * 0.5,
      time: WA_TIMING_5[Math.min(i, 4)].time,
    });
  }
  return out;
}

const CHIP_TIMING = {
  monday:    { start: 5.8, end: 6.2 },
  yesterday: { start: 9.6, end: 10.0 },
};

/* ── Message builder ──────────────────────────────────────────────────
 * Default sides match the reference structure (3 incoming, then 2
 * outgoing). Suffix override (|in / |out) wins over both default and
 * position-based fallback. For backwards-compat with saved 4-message
 * configs, slots without a suffix and without a default-side mapping
 * fall back to alternating (i % 2). */
const REFERENCE_DEFAULT_SIDES: Record<number, "left" | "right"> = {
  1: "left",
  2: "left",
  3: "left",
  4: "right",
  5: "right",
};

function buildMessages(variables: Record<string, unknown>): ChatMessage[] {
  const raw: Array<{ side: "left" | "right"; text: string }> = [];
  for (let i = 1; i <= 5; i++) {
    let text = normalizeTextVar(variables[`msg${i}`]).trim();
    if (!text) continue;
    let side: "left" | "right" = REFERENCE_DEFAULT_SIDES[i] ?? (i % 2 === 1 ? "left" : "right");
    if (text.endsWith("|in")) {
      side = "left";
      text = text.slice(0, -3).trim();
    } else if (text.endsWith("|out")) {
      side = "right";
      text = text.slice(0, -4).trim();
    }
    raw.push({ side, text });
  }
  const timing = timingForCount(Math.max(1, raw.length));
  return raw.map((m, i) => ({ ...m, ...timing[i] }));
}

/* ── Read-receipt phases ──────────────────────────────────────────────
 * The reference's tickAt() returns clock for 0.5s, sent for 0.6s,
 * delivered for 0.7s, then read. This is in REFERENCE seconds, so we
 * compute it on the reference timeline regardless of real scene
 * duration — same cadence, same look. */
type TickState = "clock" | "sent" | "delivered" | "read";

function tickStateAt(refTimeSinceSent: number): TickState {
  if (refTimeSinceSent < 0.5) return "clock";
  if (refTimeSinceSent < 1.1) return "sent";
  if (refTimeSinceSent < 1.8) return "delivered";
  return "read";
}

const ClockIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={12 * s} height={12 * s} viewBox="0 0 12 12" style={{ marginLeft: 4 * s }}>
    <circle cx="6" cy="6" r="5" fill="none" stroke="#8C8C92" strokeWidth="1.2" />
    <path d="M6 3 v3.5 l2 1" stroke="#8C8C92" strokeWidth="1.2" fill="none" strokeLinecap="round" />
  </svg>
);

const Ticks: React.FC<{ state: TickState; s: number }> = ({ state, s }) => {
  if (state === "clock") return <ClockIcon s={s} />;
  const color = state === "read" ? "#53BDEB" : "#8C8C92";
  return (
    <svg width={16 * s} height={11 * s} viewBox="0 0 16 11" style={{ marginLeft: 4 * s }}>
      <path
        d="M1 6 l3 3 l6 -7"
        stroke={color}
        strokeWidth={1.3}
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
        opacity={state === "sent" ? 0 : 1}
      />
      <path
        d="M5 6 l3 3 l7 -8"
        stroke={color}
        strokeWidth={1.3}
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
};

/* ── Background — flat warm-sand. The reference's line-art doodle
 * pattern read as visual noise behind the chat content; cleaner to
 * keep it solid so the bubbles + ticks + chips do all the heavy
 * visual lifting. */
const ChatBackground: React.FC = () => (
  <div style={{ position: "absolute", inset: 0, background: WA.bg }} />
);

/* ── Compose bar (1:1 port of ComposeBar) ─────────────────────────── */
const ComposeBar: React.FC<{ s: number }> = ({ s }) => {
  const stroke = "#1A1A1A";
  return (
    <div
      style={{
        background: WA.navBg,
        borderTop: "1px solid rgba(0,0,0,0.05)",
        padding: `${10 * s}px ${14 * s}px ${12 * s}px`,
        display: "flex",
        alignItems: "center",
        gap: 14 * s,
      }}
    >
      {/* + glyph */}
      <svg width={30 * s} height={30 * s} viewBox="0 0 30 30" style={{ flexShrink: 0 }}>
        <path d="M15 5 v20 M5 15 h20" stroke={stroke} strokeWidth="1.8" strokeLinecap="round" />
      </svg>

      {/* input pill */}
      <div
        style={{
          flex: 1,
          height: 40 * s,
          background: WA.inputBg,
          borderRadius: 22 * s,
          position: "relative",
          border: `0.5px solid ${WA.inputBorder}`,
        }}
      >
        <div
          style={{
            position: "absolute",
            right: 12 * s,
            top: "50%",
            transform: "translateY(-50%)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {/* sticker icon */}
          <svg width={28 * s} height={28 * s} viewBox="0 0 24 24" fill="none" style={{ display: "block" }}>
            <path
              d="M3 5 a2 2 0 0 1 2 -2 h10 a2 2 0 0 1 2 2 v6 l-6 6 h-6 a2 2 0 0 1 -2 -2 z M17 11 a4 4 0 0 0 -4 4 v2"
              stroke="#555"
              strokeWidth="1.5"
              fill="none"
              strokeLinejoin="round"
              strokeLinecap="round"
            />
          </svg>
        </div>
      </div>

      {/* camera */}
      <svg width={28 * s} height={24 * s} viewBox="0 0 28 24" fill="none" style={{ flexShrink: 0 }}>
        <path
          d="M3 6 h5 l2 -3 h8 l2 3 h5 a1 1 0 0 1 1 1 v14 a1 1 0 0 1 -1 1 h-22 a1 1 0 0 1 -1 -1 v-14 a1 1 0 0 1 1 -1 z"
          stroke={stroke}
          strokeWidth="1.6"
          fill="none"
          strokeLinejoin="round"
        />
        <circle cx="14" cy="14" r="4.5" stroke={stroke} strokeWidth="1.6" fill="none" />
      </svg>

      {/* mic */}
      <svg width={20 * s} height={26 * s} viewBox="0 0 20 26" fill="none" style={{ flexShrink: 0 }}>
        <rect x="7" y="2" width="6" height="13" rx="3" stroke={stroke} strokeWidth="1.6" fill="none" />
        <path
          d="M3 12 a7 7 0 0 0 14 0 M10 19 v4 M7 23 h6"
          stroke={stroke}
          strokeWidth="1.6"
          fill="none"
          strokeLinecap="round"
        />
      </svg>
    </div>
  );
};

/* ── Date chip (1:1 port) ───────────────────────────────────────────── */
const DateChip: React.FC<{ label: string; chipProgress: number; s: number }> = ({ label, chipProgress, s }) => {
  if (chipProgress <= 0) return null;
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        margin: `${12 * s}px 0 ${8 * s}px`,
        opacity: chipProgress,
        transform: `scale(${0.88 + 0.12 * chipProgress})`,
      }}
    >
      <div
        style={{
          background: WA.chipBg,
          color: WA.chipText,
          padding: `${7 * s}px ${16 * s}px`,
          borderRadius: 9 * s,
          fontSize: 17 * s,
          fontWeight: 600,
          boxShadow: `0 ${1 * s}px ${1.5 * s}px rgba(0,0,0,0.05)`,
        }}
      >
        {label}
      </div>
    </div>
  );
};

/* ── Typing bubble (1:1 port — gentle 1.5 Hz ripple) ────────────────── */
const TypingBubble: React.FC<{
  side: "left" | "right";
  pop: number;
  realTimeSeconds: number;
  s: number;
}> = ({ side, pop, realTimeSeconds, s }) => {
  if (pop <= 0) return null;
  const isOut = side === "right";
  const dotColor = isOut ? "#6B8A55" : "#8C8C92";
  return (
    <div
      style={{
        display: "flex",
        justifyContent: isOut ? "flex-end" : "flex-start",
        padding: `${2 * s}px ${10 * s}px`,
        opacity: pop,
        transform: `scale(${0.9 + 0.1 * pop})`,
        transformOrigin: isOut ? "right bottom" : "left bottom",
      }}
    >
      <div
        style={{
          background: isOut ? WA.outgoingBubble : WA.incomingBubble,
          borderRadius: 14 * s,
          borderTopLeftRadius: isOut ? 14 * s : 2 * s,
          borderTopRightRadius: isOut ? 2 * s : 14 * s,
          padding: `${10 * s}px ${12 * s}px`,
          display: "flex",
          gap: 5 * s,
          alignItems: "center",
          boxShadow: `0 ${1 * s}px ${1 * s}px rgba(0,0,0,0.06)`,
        }}
      >
        {[0, 1, 2].map((i) => {
          const phase = (realTimeSeconds * 1.6 + i * 0.2) % 1;
          const y = Math.sin(phase * Math.PI * 2) * 2.5 * s;
          const op = 0.45 + 0.55 * Math.max(0, Math.sin(phase * Math.PI));
          return (
            <div
              key={i}
              style={{
                width: 6 * s,
                height: 6 * s,
                borderRadius: 3 * s,
                background: dotColor,
                transform: `translateY(${-y}px)`,
                opacity: op,
              }}
            />
          );
        })}
      </div>
    </div>
  );
};

/* ── Schema ─────────────────────────────────────────────────────────────
 * Defaults teach the AI the WhatsApp 5-bubble + 2-chip rhythm. msg5,
 * dateChip1, dateChip2 are technically optional — leave them blank and
 * the timing redistributes across however many messages are present. */
/* Prescriptive guidance baked into descriptions: the AI sees these in
 * the per-call template brief, so spelling out "use 3-4 by default,
 * 5+chips only when time genuinely spans days" beats every prompt-
 * level reminder. msg4/msg5 are nominally not required; leaving them
 * blank produces a 3- or 4-message variant naturally. */
export const socialConversationSchema: Record<string, VariableField> = {
  msg1: {
    type: "string",
    label: "Message 1 (received)",
    default: "Have you tried it yet?",
    required: true,
    description:
      "First message — left/received by default. Append |in or |out to override side. " +
      "Aim for 3-4 messages total (most common). Use 5 with date chips only when narrative spans days AND scene is 10s+.",
  },
  msg2: {
    type: "string",
    label: "Message 2 (received or sent)",
    default: "It saves me hours every week",
    required: true,
    description: "Second message — left/received by default. Override with |out for ping-pong.",
  },
  msg3: {
    type: "string",
    label: "Message 3 (received)",
    default: "And the team loves it",
    required: true,
    description: "Third message — left/received by default. Skip (leave blank) for a 2-message exchange.",
  },
  msg4: {
    type: "string",
    label: "Message 4 (sent)",
    default: "Sounds great — sharing access now",
    description: "Fourth message — right/sent by default. Optional. Most chats end here on the reply.",
  },
  dateChip1: {
    type: "string",
    label: "Date chip 1",
    default: "",
    description:
      "Optional date label between message 3 and message 4 (e.g. 'Monday'). Use only when the conversation explicitly spans a real time gap. Leave blank otherwise.",
  },
  dateChip2: {
    type: "string",
    label: "Date chip 2",
    default: "",
    description:
      "Optional date label between message 4 and message 5 (e.g. 'Yesterday'). Same rule as dateChip1.",
  },
  msg5: {
    type: "string",
    label: "Message 5 (sent)",
    default: "",
    description: "Fifth message — right/sent by default. Optional. Use only for the 5-message + chips 'spans days' pattern.",
  },
};

/* Default = 4-message ping-pong (the canonical SaaS chat shape).
 * msg5 + chips are intentionally empty so the picker preview shows the
 * standard rhythm, not the 5-message "spans days" variant. */
const sharedMessages = {
  msg1: "Have you tried it yet?",
  msg2: "It saves me hours every week",
  msg3: "And the team loves it",
  msg4: "Sounds great — sharing access now",
  msg5: "",
  dateChip1: "",
  dateChip2: "",
};

export const socialMessengerDefaults: Record<string, unknown> = {
  theme: "messenger",
  ...sharedMessages,
};

export const socialWhatsappDefaults: Record<string, unknown> = {
  theme: "whatsapp",
  ...sharedMessages,
};

/* ── Template component ────────────────────────────────────────────── */
export const SocialConversationTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  progress,
  width,
  height,
  sceneDuration,
  safeZone,
}) => {
  const theme =
    String(variables.theme || "messenger").toLowerCase() === "whatsapp"
      ? "whatsapp"
      : "messenger";
  const isWhatsApp = theme === "whatsapp";

  if (isWhatsApp) {
    return (
      <WhatsAppRender
        variables={variables}
        progress={progress}
        width={width}
        height={height}
        sceneDuration={sceneDuration}
        safeZone={safeZone}
      />
    );
  }
  return (
    <MessengerRender
      variables={variables}
      progress={progress}
      width={width}
      height={height}
      sceneDuration={sceneDuration}
      safeZone={safeZone}
    />
  );
};

/* ── WhatsApp render (1:1 port of ChatScene) ───────────────────────── */
interface RenderProps {
  variables: Record<string, unknown>;
  progress: number;
  width: number;
  height: number;
  sceneDuration: number;
  safeZone: SceneTemplateProps["safeZone"];
}

const WhatsAppRender: React.FC<RenderProps> = ({
  variables,
  progress,
  width,
  height,
  sceneDuration,
  safeZone,
}) => {
  /* Reference is 534×996 (a portrait phone). On portrait the chat
   * fills the full canvas width and `s` derives from it. On landscape
   * (16:9), use the SHORT edge for typography scale (so bubbles + fonts
   * match portrait), but make the chat column ~72% of width so the
   * chat fills the landscape frame properly instead of clustering in
   * a narrow phone-shaped strip with empty bg on both sides. */
  const isLandscape = width > height;
  const colWidth = isLandscape ? width * 0.72 : width;
  const colLeft = (width - colWidth) / 2;
  const s = Math.min(width, height) / 534;
  const messages = buildMessages(variables);
  const realTimeSeconds = progress * sceneDuration;
  const refT = progress * REF_DURATION;
  /* Insta/TikTok overlay UI eats roughly the top ~10-13% of a 9:16
   * frame. Bump the global safeZone.top to leave real breathing room
   * above the first message. */
  const topPad = Math.max(safeZone.top, height * 0.08);

  /* Date-chip values — empty string suppresses the chip. */
  const chip1Label = normalizeTextVar(variables.dateChip1).trim();
  const chip2Label = normalizeTextVar(variables.dateChip2).trim();

  /* Easing helper — pop-in ramp matching reference popIn(t, s, dur). */
  const popIn = (t: number, start: number, dur = 0.4): number => {
    if (t <= start) return 0;
    if (t >= start + dur) return 1;
    return easeOutBack((t - start) / dur);
  };

  /* Linear ramp for chip animations (0..1 across [start, end]). */
  const ramp = (t: number, start: number, end: number): number => {
    if (t <= start) return 0;
    if (t >= end) return 1;
    return (t - start) / (end - start);
  };

  return (
    <div
      style={{
        width,
        height,
        background: WA.bg,
        position: "relative",
        overflow: "hidden",
        fontFamily: '\'Inter\', -apple-system, "SF Pro Text", system-ui',
      }}
    >
      <ChatBackground />
      {/* Centered chat column. On portrait colWidth = width (fills canvas);
       * on landscape it's a phone-shaped strip centered horizontally with
       * the bg color showing in the side margins. */}
      <div
        style={{
          position: "absolute",
          left: colLeft,
          width: colWidth,
          top: 0,
          height,
          display: "flex",
          flexDirection: "column",
        }}
      >
      <div style={{ flex: 1, position: "relative", overflow: "hidden" }}>
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: 0,
            display: "flex",
            flexDirection: "column",
            gap: 2 * s,
            padding: `${topPad}px 0 ${10 * s}px`,
          }}
        >
          {messages.map((msg, i) => {
            const typingPop = popIn(refT, msg.typingStart, 0.25);
            const typingFade = interpolate(
              refT,
              [msg.bubbleStart - 0.1, msg.bubbleStart],
              [1, 0],
              CLAMP,
            );
            const showTyping = refT >= msg.typingStart && refT < msg.bubbleStart;
            const bubblePop = popIn(refT, msg.bubbleStart, 0.4);
            const showBubble = refT >= msg.bubbleStart;

            const isOut = msg.side === "right";

            /* Tick state ticks across the full reference timeline from
             * the moment this message landed. */
            const refSinceSent = refT - msg.bubbleStart - 0.4; // start counting after pop-in lands
            const tickState = isOut ? tickStateAt(Math.max(0, refSinceSent)) : "read";

            /* Chip: dateChip1 between msg3 and msg4, dateChip2 between
             * msg4 and msg5. Render the chip BEFORE the message it
             * precedes, so it stacks visually in the right place. */
            const chipBeforeThis: { label: string; progress: number } | null = (() => {
              if (i === 3 && chip1Label) {
                return { label: chip1Label, progress: ramp(refT, CHIP_TIMING.monday.start, CHIP_TIMING.monday.end) };
              }
              if (i === 4 && chip2Label) {
                return { label: chip2Label, progress: ramp(refT, CHIP_TIMING.yesterday.start, CHIP_TIMING.yesterday.end) };
              }
              return null;
            })();

            return (
              <React.Fragment key={i}>
                {chipBeforeThis && <DateChip label={chipBeforeThis.label} chipProgress={chipBeforeThis.progress} s={s} />}

                {showTyping && (
                  <div style={{ opacity: typingPop * typingFade }}>
                    <TypingBubble
                      side={msg.side}
                      pop={typingPop}
                      realTimeSeconds={realTimeSeconds}
                      s={s}
                    />
                  </div>
                )}

                {showBubble && (
                  isOut ? (
                    <OutgoingBubble pop={bubblePop} time={msg.time} tickState={tickState} s={s}>
                      {msg.text}
                    </OutgoingBubble>
                  ) : (
                    <IncomingBubble pop={bubblePop} time={msg.time} s={s}>
                      {msg.text}
                    </IncomingBubble>
                  )
                )}
              </React.Fragment>
            );
          })}

          <div style={{ height: 12 * s }} />
        </div>
      </div>

      <ComposeBar s={s} />
      </div>{/* end centered chat column */}
    </div>
  );
};

/* ── Incoming/Outgoing bubbles (1:1 port, no reply quote) ─────────── */
const IncomingBubble: React.FC<{
  children: React.ReactNode;
  time: string;
  pop: number;
  s: number;
}> = ({ children, time, pop, s }) => (
  <div
    style={{
      display: "flex",
      justifyContent: "flex-start",
      padding: `${2 * s}px ${10 * s}px`,
      opacity: pop,
      transform: `translateY(${(1 - pop) * 6 * s}px) scale(${0.97 + 0.03 * pop})`,
      transformOrigin: "left bottom",
    }}
  >
    <div
      style={{
        maxWidth: "82%",
        background: WA.incomingBubble,
        borderRadius: 10 * s,
        borderTopLeftRadius: 2 * s,
        padding: `${12 * s}px ${16 * s}px ${11 * s}px`,
        fontSize: 23 * s,
        lineHeight: `${29 * s}px`,
        color: WA.text,
        boxShadow: `0 ${1 * s}px ${1 * s}px rgba(0,0,0,0.06)`,
        position: "relative",
      }}
    >
      <div style={{ paddingRight: 64 * s }}>{children}</div>
      <div
        style={{
